from collections import Counter,deque

def comps(g, conn=4):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 if conn==8: dirs += [(1,1),(1,-1),(-1,1),(-1,-1)]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen: continue
   col=g[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dx,dy in dirs:
     nx,ny=x+dx,y+dy
     if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==col:
      seen.add((nx,ny)); q.append((nx,ny))
   out.append((col,cells))
 return out

def changed(a,b): return [(r,c,a[r][c],b[r][c]) for r in range(len(a)) for c in range(len(a[0])) if a[r][c]!=b[r][c]]
for n,a,b in pairs:
 print('\n',n, 'bg',Counter(sum(a,[])).most_common(1)[0], 'changed',Counter((x,y) for _,_,x,y in changed(a,b)))
 print('diff comps',[(col,len(cs),(min(r for r,c in cs),min(c for r,c in cs),max(r for r,c in cs),max(c for r,c in cs))) for col,cs in comps(a) if any((r,c) in {(x,y) for x,y,_,_ in changed(a,b)} for r,c in cs)])

def lshape(comp):
 rs=[r for r,c in comp]; cs=[c for r,c in comp]; r0,r1=min(rs),max(rs);c0,c1=min(cs),max(cs)
 h,w=r1-r0+1,c1-c0+1
 if len(comp)!=h+w-1:return False
 # fills one bounding edge row and one edge column
 return any(all((rr,cc) in comp for cc in range(c0,c1+1)) and all((rr,cc) in comp for rr in range(r0,r1+1)) for rr in (r0,r1) for cc in (c0,c1))

def rect(cells):return (min(r for r,c in cells),min(c for r,c in cells),max(r for r,c in cells),max(c for r,c in cells))
def boxdist(a,b):
 ar0,ac0,ar1,ac1=rect(a);br0,bc0,br1,bc1=rect(b)
 return max(0,ar0-br1,br0-ar1)+max(0,ac0-bc1,bc0-ac1)
for n,a,b in pairs:
 ch=changed(a,b); tgt={(r,c) for r,c,_,_ in ch}; target=next((co,cs) for co,cs in comps(a) if any(p in tgt for p in cs))
 marker=[(co,cs) for co,cs in comps(a) if lshape(set(cs))]
 print('\n',n,'dest',ch[0][3], 'target',target[0],len(target[1]),rect(target[1]),'markers',[(x,len(y),rect(y)) for x,y in marker])
 if marker:
  mcol,mcs=marker[0][0],set(marker[0][1]);print('dist',boxdist(mcs,set(target[1])))
  candidates=[]
  for co,cs in comps(a):
   if co==Counter(sum(a,[])).most_common(1)[0][0] or (co,cs)==target: continue
   candidates.append((boxdist(mcs,set(cs)),co,len(cs),rect(cs), lshape(set(cs))))
